"""CSV outputs: UTF-8 without BOM, RFC 4180, byte-exact headers (golden-file tested)."""

from __future__ import annotations

import csv
import io
import re
from collections.abc import Iterable, Sequence

from snowth_my_net.snmp.target import split_host_port
from snowth_my_net.snmp.values import one_line

# Headers are written literally, never generated by the csv module: their quoting is part of
# the contract with consumers.
DEVICES_HEADER = ('"Device Name","Device Details","IP Address",Location,Model,Serial,Vendor,'
                  '"Operating System","OS Version","MAC Address"')
DEVICES_TYPE_COLUMN = ',"Device Type"'
NODES_HEADER = '"MAC Address",Vendor,"IP Address","DNS Name",Switch,Port,VLAN,"Last Seen"'
def nodes_header(include_name: bool, include_description: bool) -> str:
    """The columns of ``nodes.csv``: the ones an importer knows, and only what was asked for
    in front of them (both off by default, so that file never changes shape on its own)."""
    front = (["Name"] if include_name else []) + (["Description"] if include_description else [])
    return ",".join([*front, NODES_HEADER]) if front else NODES_HEADER
LINKS_HEADER = "Local Device,Local Port,Remote Device,Remote Port,Protocol,Last Seen"

EOL = {"crlf": "\r\n", "lf": "\n"}


class EmptyExport(Exception):
    """A CSV would have no data row: it is neither written nor pushed."""


def render_csv(header: str, rows: Iterable[Sequence[str]], line_terminator: str = "crlf") -> bytes:
    eol = EOL[line_terminator]
    buf = io.StringIO(newline="")
    buf.write(header + eol)
    writer = csv.writer(buf, lineterminator=eol, quoting=csv.QUOTE_MINIMAL)
    writer.writerows(rows)
    return buf.getvalue().encode("utf-8")


def natural_key(text: str) -> list:
    return [int(part) if part.isdigit() else part for part in re.split(r"(\d+)", text.casefold())]


def device_rows(devices: Sequence, names: dict[int, str], include_type: bool) -> list[list[str]]:
    """``devices`` are state rows (sqlite3.Row or mappings) of the devices to export."""
    rows = []
    for d in devices:
        ip = split_host_port(d["mgmt_address"])[0]
        row = [
            names[d["id"]],
            one_line(d["sys_descr"] or ""),
            ip,
            one_line(d["sys_location"] or ""),
            d["model"] or "",
            d["serial"] or "",
            d["vendor"] or "",
            d["os_name"] or "",
            d["os_version"] or "",
            d["base_mac"] or "",
        ]
        if include_type:
            row.append(d["device_type"] or "")
        rows.append(row)
    rows.sort(key=lambda r: (natural_key(r[0]), r[2]))
    return rows


def devices_csv(devices: Sequence, names: dict[int, str], include_type: bool,
                line_terminator: str, allow_empty: bool = False) -> bytes:
    rows = device_rows(devices, names, include_type)
    if not rows and not allow_empty:
        raise EmptyExport("devices.csv would have no data row")
    header = DEVICES_HEADER + (DEVICES_TYPE_COLUMN if include_type else "")
    return render_csv(header, rows, line_terminator)
